operations.search:
const actionId =
  typeof actionOrId ===
    "string"
    ? actionOrId
    : actionOrId?.id;


if (
  !actionId
) {
  return false;
}


return (
  FRAME_CONN_NO_ROLL_ACTIONS
    .has(
      actionId
    )
);

operations.replace:
const actionId =
  typeof actionOrId ===
    "string"
    ? actionOrId
    : actionOrId?.id;

const actionCategory =
  typeof actionOrId ===
    "object"
    ? actionOrId?.category ?? null
    : null;


if (
  !actionId
) {
  return false;
}


if (
  actionCategory ===
    "protocol" ||
  String(actionId)
    .startsWith(
      "protocol."
    )
) {
  return true;
}


return (
  FRAME_CONN_NO_ROLL_ACTIONS
    .has(
      actionId
    )
);
